const mondayOf = (d: Date) => { const x = new Date(d.getFullYear(), d.getMonth(), d.getDate()); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; };
const parseBonDate = (txt?: string): Date | null => {
  const mm = (txt || '').match(/(\d{1,2})\.(\d{1,2})\.(\d{2,4})/);
  if (!mm) return null;
  const yy = Number(mm[3]) < 100 ? 2000 + Number(mm[3]) : Number(mm[3]);
  return new Date(yy, Number(mm[2]) - 1, Number(mm[1]));
};
